fn yaml_scalar(line: &str, key: &str) -> Option<String> {
    let t = line.trim();
    if t.starts_with('-') {
        return None;
    }
    let mut head = String::from(key);
    head.push(':');
    let rest = t.strip_prefix(&head)?;
    let v = rest.trim().trim_matches('"').trim_matches('\'').trim();
    if v.is_empty() {
        return None;
    }
    Some(v.to_string())
}

