pub fn expr_slug(expr: &str) -> String {
    let cut = expr.split("==").next().unwrap_or(expr);
    let cut = cut.trim();
    let cut = cut.strip_prefix("hard:").unwrap_or(cut).trim();
    let mut s = String::new();
    for c in cut.chars() {
        if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
            s.push(c);
        } else if (c == ' ' || c == ',' || c == '/' || c == '.') && s.is_empty() == false {
            if s.ends_with('_') == false {
                s.push('_');
            }
        }
    }
    while s.ends_with('_') {
        s.pop();
    }
    if s.is_empty() {
        return String::from("item");
    }
    if s.len() > 72 {
        s.truncate(72);
    }
    s
}

