fn luhn_ok(digits: &[u8]) -> bool {
    if digits.len() < 13 || digits.len() > 19 {
        return false;
    }
    let mut sum = 0u32;
    let mut alt = false;
    for d in digits.iter().rev() {
        let mut n = *d as u32;
        if alt {
            n *= 2;
            if n > 9 {
                n -= 9;
            }
        }
        sum += n;
        alt = !alt;
    }
    sum % 10 == 0
}

fn has_credit_card(text: &str) -> bool {
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    let mut i = 0usize;
    while i < n {
        if chars[i].is_ascii_digit() {
            let mut digits: Vec<u8> = Vec::new();
            let mut j = i;
            while j < n {
                let ch = chars[j];
                if ch.is_ascii_digit() {
                    digits.push((ch as u8) - b'0');
                    j += 1;
                } else if (ch == ' ' || ch == '-') && digits.is_empty() == false {
                    j += 1;
                } else {
                    break;
                }
            }
            if luhn_ok(&digits) {
                return true;
            }
            i += 1;
        } else {
            i += 1;
        }
    }
    false
}

fn has_phone(text: &str) -> bool {
    let mut digits = String::new();
    for c in text.chars() {
        if c.is_ascii_digit() {
            digits.push(c);
        } else if c == '+' || c == '-' || c == ' ' || c == '(' || c == ')' || c == '.' {
            continue;
        } else {
            if digits.len() == 10 || digits.len() == 11 {
                return true;
            }
            digits.clear();
        }
    }
    digits.len() == 10 || digits.len() == 11
}

