    #[test]
    fn scan_kernel_requires_live_fold() {
        match scan_kernel_loads_policy_system("fn compile_live_walls() {}") {
            Err(e) => must(e.contains("missing")),
            Ok(_) => std::process::abort(),
        }
        let good = "use aep_policy_system_admit::compile_policy_system_walls;\n\"aep-policy-system-admit\"";
        match scan_kernel_loads_policy_system(good) {
            Ok(v) => must(v.contains("ok kernel")),
            Err(_) => std::process::abort(),
        }
    }

    #[test]
    fn scan_readme_rejects_join_meet_driver() {
        let bad = super::join_parts(&["bound to hyperlattice nodes via ", "join", "/", "meet"]);
        match scan_readme_live_admit(&bad) {
            Err(e) => must(e.contains("README")),
            Ok(_) => std::process::abort(),
        }
        let good = "Live Admit GAP files\nLoaded as live Admit walls on the kernel collect-all pass";
        match scan_readme_live_admit(good) {
            Ok(v) => must(v.contains("ok README")),
            Err(_) => std::process::abort(),
        }
    }

